"""i18n for clickandfood.global — DE is the source language; EN, FR, IT, RM translations.
RM = Romansh (Grischun). Lookup falls back to the German source string."""

LANGS = ["de", "en", "fr", "it", "rm"]
NAMES = {"de": "Deutsch", "en": "English", "fr": "Français", "it": "Italiano", "rm": "Rumantsch"}
LOCALES = {"de": "de_CH", "en": "en_CH", "fr": "fr_CH", "it": "it_CH", "rm": "rm_CH"}

def tr(s, lang):
    """Translate source string s into lang. Fallback: s (German)."""
    if lang == "de" or not s:
        return s
    e = T.get(s)
    if e and lang in e:
        return e[lang]
    return s

