def tr_cuisine(label, lang):
    """Translate a ' · '-joined cuisine label; unknown terms stay as-is."""
    if not label or lang == "de":
        return label
    parts = [p.strip() for p in label.split("·")]
    return " · ".join(tr(p, lang) for p in parts)

# ============ HTML helpers shared by generator + build script ============
BASE = "https://clickandfood.global"

def lang_prefix(lang):
    return "" if lang == "de" else "/" + lang

def localized(path, lang):
    """path like '/restaurants/x/' -> language-prefixed path."""
    if lang == "de":
        return path
    return "/" + lang + (path if path.startswith("/") else "/" + path)

def hreflang_block(path):
    """Full hreflang cluster for a page path (path starts with /, German version)."""
    out = []
    for l in LANGS:
        out.append('<link rel="alternate" href="%s" hreflang="%s">' % (BASE + localized(path, l), l))
    out.append('<link rel="alternate" href="%s" hreflang="x-default">' % (BASE + localized(path, "en")))
    return "\n".join(out)

def lang_switcher(path, lang):
    """Compact dropdown language switcher. path = German page path starting with /."""
    items = []
    for l in LANGS:
        href = localized(path, l)
        cls = ' class="on"' if l == lang else ""
        items.append('<a href="%s"%s data-lang="%s" role="menuitem">%s <span>%s</span></a>'
                     % (href, cls, l, l.upper(), NAMES[l]))
    return ('<div class="langsw">'
            '<button class="langsw-btn" type="button" aria-haspopup="true" aria-expanded="false">'
            '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M3.6 9h16.8M3.6 15h16.8M12 3a15 15 0 0 1 0 18M12 3a15 15 0 0 0 0 18"/></svg>'
            + lang.upper() +
            ' <svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M6 9l6 6 6-6"/></svg>'
            '</button>'
            '<div class="langsw-menu" role="menu">' + "".join(items) + '</div>'
            '</div>')

