REDIRECT_SCRIPT = """<script>
(function(){
  try{
    var S=['de','en','fr','it','rm'];
    var path=location.pathname; // German pages live at root
    var stored='';
    try{stored=localStorage.getItem('cf-lang')||''}catch(e){}
    if(stored){
      if(stored!=='de'&&S.indexOf(stored)>-1){location.replace('/'+stored+path+location.search+location.hash)}
      return;
    }
    var navs=navigator.languages||[navigator.language||'en'];
    var pick='en';
    for(var i=0;i<navs.length;i++){
      var s=(navs[i]||'').slice(0,2).toLowerCase();
      if(S.indexOf(s)>-1){pick=s;break}
    }
    if(pick!=='de'){location.replace('/'+pick+path+location.search+location.hash)}
  }catch(e){}
})();
</script>
<script>__LANGSW_JS__</script>"""

LANGSW_JS = """
// language dropdown toggle
document.addEventListener('click',function(e){
  var sw=document.querySelector('.langsw');
  var btn=e.target.closest('.langsw-btn');
  if(btn&&sw){e.preventDefault();var open=sw.classList.toggle('open');btn.setAttribute('aria-expanded',open?'true':'false');return}
  if(sw&&sw.classList.contains('open')&&!e.target.closest('.langsw')){sw.classList.remove('open')}
  var a=e.target.closest('.langsw-menu a');
  if(a){try{localStorage.setItem('cf-lang',a.getAttribute('data-lang'))}catch(x){}}
});
document.addEventListener('keydown',function(e){
  if(e.key==='Escape'){var sw=document.querySelector('.langsw.open');if(sw)sw.classList.remove('open')}
});
"""

